mapper.select:
select * from (
    select row_number() over (order by id desc) as rn, 
    from ${table}



) t
where t.rn > #{offset} and t.rn <= #{offset} + #{limit}
order by t.rn

select op_type as opType, count(1) as totalCount from ${table} where 1 = 1
and user_id = #{userId}
and menu_id = #{menuId}
and (menu_name like '%' + #{keyword} + '%' or page_url like '%' + #{keyword} + '%' or client_ip like '%' + #{keyword} + '%')
and (user_name like '%' + #{userKeyword} + '%' or login_name like '%' + #{userKeyword} + '%')
group by op_type

mapper.delete:
delete from ${table}
where (modedatacreatedate < #{beforeDate}
       or (modedatacreatedate = #{beforeDate} and modedatacreatetime < #{beforeTime}))
